export type ResearchStatus = "In preparation" | "In progress" | "Published" | "Complete";

export type MetricCard = { label: string; value: string; detail?: string };
export type ReportTable = { caption?: string; headers: string[]; rows: string[][] };
export type ReportFigure = { src: string; alt: string; caption: string; width: number; height: number };
export type Diagram = { title: string; caption: string; kind: "flow" | "loop"; nodes: { id: string; label: string }[]; links: { from: string; to: string; label?: string }[] };
export type Callout = { label: string; text: string };
export type ReportSection = { id: string; title: string; paragraphs?: string[]; callout?: Callout; metrics?: MetricCard[]; table?: ReportTable; tables?: ReportTable[]; figures?: ReportFigure[]; diagram?: Diagram };

export type Company = { slug: string; name: string; sector: string; industry?: string; ticker?: string; exchange?: string; headquarters?: string; coverageStatus: ResearchStatus; publicationDate?: string; readingTime?: string; pdfUrl?: string; reportSummary?: string; investmentSnapshot?: MetricCard[]; sectionOrder?: string[]; sections?: ReportSection[]; relatedSlugs?: string[] };

const appleSections: ReportSection[] = [
  { id: "executive-summary", title: "Executive Summary", paragraphs: ["Apple is not presented here as a business that needs explosive growth every year. The research instead makes a long-term case for a company that already produces substantial revenue, profit, and cash flow—and whose task is to keep customers engaged enough to buy the next device, add another service, and remain inside the ecosystem.", "The core case rests on customer loyalty, premium pricing, hardware and software integration, and an expanding Services business that provides recurring revenue. The principal constraints are a mature smartphone market, the iPhone’s importance to revenue, regulatory pressure around the App Store, competition in AI, supply-chain disruption, and sensitivity to premium consumer spending."], callout: { label: "Author view", text: "The supplied thesis supports a positive ten-year ownership view, based on the expectation that Apple can remain a phenomenal business rather than become the fastest-growing company." } },
  { id: "business-overview", title: "Business Overview", paragraphs: ["Apple sells a broad group of products—iPhone, Mac, iPad, Apple Watch, AirPods, and accessories—alongside a growing set of Services. The iPhone remains the largest revenue generator and, in this research, the gateway into the wider Apple ecosystem.", "Services include App Store commissions, Apple Music, iCloud+, Apple TV+, Apple Arcade, AppleCare, Apple Pay, and Apple Fitness+. The research emphasizes that the company’s activity extends beyond selling a single device: a purchase can connect customers to more devices and to ongoing services."] },
  { id: "business-model", title: "Business Model", paragraphs: ["Apple combines product sales with recurring Services revenue. The author’s central observation is that the company has built a business around keeping customers within an integrated ecosystem: an iPhone can lead to an Apple Watch, AirPods, a MacBook, and paid services such as iCloud+.", "The resulting model blends periodic hardware purchases with services that can produce income month after month. This distinction matters because subscriptions are described as more predictable than relying solely on upgrade cycles."], diagram: { title: "Apple ecosystem loop", caption: "Author’s framework: the iPhone introduces customers to connected devices and Services, reinforcing retention and repeat purchasing.", kind: "loop", nodes: [{ id: "iphone", label: "iPhone" }, { id: "devices", label: "Connected devices" }, { id: "services", label: "Services" }, { id: "retention", label: "Customer retention" }], links: [{ from: "iphone", to: "devices" }, { from: "devices", to: "services" }, { from: "services", to: "retention" }, { from: "retention", to: "iphone", label: "repeat purchase" }] } },
  { id: "revenue-breakdown", title: "Revenue Breakdown", paragraphs: ["The research separates Apple’s revenue into Products and Services. Products comprise iPhone, Mac, iPad, Apple Watch, AirPods, and accessories. Services comprise the company’s listed subscription, transaction, support, and content offerings.", "The supplied segment chart presents the approximate FY2025 contribution of iPhone, Services, Mac, iPad, and Wearables & Accessories. It should be read as the author’s visual overview of the major segments."], diagram: { title: "Revenue architecture", caption: "Author’s framework: Apple’s revenue is organized around Products and Services, with Services providing a recurring-revenue component.", kind: "flow", nodes: [{ id: "products", label: "Products" }, { id: "services", label: "Services" }, { id: "recurring", label: "Recurring revenue" }], links: [{ from: "services", to: "recurring" }] }, figures: [{ src: "/research/apple/Segment_Revenue_Chart_v1.png", alt: "Bar chart showing approximate Apple revenue by segment in fiscal year 2025, with iPhone the largest segment followed by Services.", caption: "Approximate contribution of Apple’s major segments in FY2025, as supplied by the author.", width: 626, height: 403 }] },
  { id: "competitive-advantages", title: "Competitive Advantages", paragraphs: ["The research identifies Apple’s brand, loyal customers, high switching costs, tight hardware-and-software integration, premium pricing, and cash resources as its principal advantages. The emphasis is not on one feature in isolation, but on the way these elements work together.", "The author’s conclusion is that Apple is fundamentally in the customer-loyalty business: the iPhone brings customers in, the ecosystem encourages them to stay, and Services continue the commercial relationship after a device has been purchased."] },
  { id: "industry-context", title: "Industry Context", paragraphs: ["The supplied research characterizes the smartphone market as mature, which makes growth harder to sustain at earlier rates. It also identifies growing competition in AI and increasing regulatory pressure, including App Store antitrust concerns, as important parts of the operating context.", "The author notes potential future areas of growth—Services, AI integration, wearables, health technology, financial services, spatial computing, and emerging markets—while retaining the view that Apple often enters markets later after refining the product experience."] },
  { id: "financial-performance", title: "Financial Performance", paragraphs: ["The financial record supports the research’s focus on consistency. Revenue rose from US$365.8B in FY2021 to US$416.2B in FY2025, with a decline in FY2023 before growth resumed. Net income remained substantial throughout the period and reached US$112.0B in FY2025.", "Gross margin increased from 41.8% in FY2021 to 46.9% in FY2025, while operating margin increased from 29.8% to 32.0%. The author attributes improving margins to higher-priced products and growth in Services, and describes cash flow as one of Apple’s greatest strengths."], table: { caption: "Selected financial data from the supplied Apple database. US$ billions except per-share amounts, margins, ROE, and approximate valuation fields.", headers: ["Fiscal year", "Revenue", "Net income", "Gross margin", "Operating margin", "Free cash flow"], rows: [["2021", "365.8", "94.7", "41.8%", "29.8%", "93.0"], ["2022", "394.3", "99.8", "43.3%", "30.3%", "111.4"], ["2023", "383.3", "97.0", "44.1%", "30.7%", "99.6"], ["2024", "391.0", "93.7", "46.2%", "31.0%", "108.8"], ["2025", "416.2", "112.0", "46.9%", "32.0%", "98.8"]], }, figures: [{ src: "/research/apple/Revenue_Growth_Chart_v1.png", alt: "Line chart showing Apple revenue from fiscal year 2021 through 2025.", caption: "Apple revenue trend, FY2021–FY2025. The FY2025 figure follows the supplied Apple database: US$416.2B.", width: 629, height: 414 }, { src: "/research/apple/Net_Income_Chart_v1.png", alt: "Line chart showing Apple net income from fiscal year 2021 through 2025.", caption: "Apple net-income trend, FY2021–FY2025, using the supplied research figures.", width: 621, height: 397 }, { src: "/research/apple/Margin_Chart_v1.png", alt: "Line chart comparing Apple gross margin and operating margin from fiscal year 2021 through 2025.", caption: "Gross-margin and operating-margin trend, FY2021–FY2025. The 2024 operating margin follows the supplied Apple database: 31.0%.", width: 624, height: 400 }] },
  { id: "capital-allocation", title: "Capital Allocation", paragraphs: ["The research presents Apple’s cash generation as a source of flexibility. It identifies investment in research and development, share repurchases, dividends, acquisitions, and new-product development as the principal uses of that capacity.", "The investment thesis treats large share buybacks as part of the long-term case, alongside the ability to invest in opportunities the company believes are important. The supplied material does not provide a detailed capital-allocation framework or assess the returns on individual decisions."], diagram: { title: "Capital allocation flow", caption: "Author’s framework: cash generation supports investment, shareholder returns, acquisitions, and product development.", kind: "flow", nodes: [{ id: "cash", label: "Cash generation" }, { id: "r-and-d", label: "R&D" }, { id: "buybacks", label: "Buybacks & dividends" }, { id: "growth", label: "Acquisitions & products" }], links: [{ from: "cash", to: "r-and-d" }, { from: "cash", to: "buybacks" }, { from: "cash", to: "growth" }] } },
  { id: "risks", title: "Risks", paragraphs: ["The research identifies slower iPhone upgrades as the principal business risk because the iPhone remains a large part of revenue. A mature smartphone market makes this issue more consequential than it would be for a faster-growing category.", "Other stated risks are regulatory pressure on the App Store, strong competition in AI, supply-chain disruption, dependence on premium consumer spending, and the possibility that even a strong business is affected by economic slowdowns."] },
  { id: "valuation-context", title: "Valuation Context", paragraphs: ["The supplied database records approximate historical P/E values of about 29× in FY2021, 24× in FY2022, 31× in FY2023, 36× in FY2024, and 33× in FY2025. These figures provide historical context only.", "The research does not supply a discounted-cash-flow model, a fair-value estimate, a target price, or a valuation conclusion. None is inferred here."], table: { caption: "Approximate historical P/E values from the supplied Apple database.", headers: ["Fiscal year", "Approximate P/E"], rows: [["2021", "~29×"], ["2022", "~24×"], ["2023", "~31×"], ["2024", "~36×"], ["2025", "~33×"]] } },
  { id: "investment-thesis", title: "Investment Thesis", paragraphs: ["The supplied thesis answers yes to the question of whether Apple would be an investment for the next ten years—not because the author expects it to double overnight, but because the author expects it to remain a phenomenal business. The bull case rests on the ecosystem, recurring Services revenue, brand, premium pricing, cash flow, customer loyalty, and share repurchases.", "The bear case centers on growth: the smartphone market has matured and iPhone revenue remains important. The author also treats AI execution as an open question, while identifying Services growth, improved AI integration, healthcare, future wearables and spatial computing, buybacks, and emerging markets as potential catalysts."], callout: { label: "Final decision", text: "The author’s conclusion is a positive long-term ownership view, grounded in Apple’s ability to keep making money through different economic and market conditions—not in an expectation that it will be the fastest-growing or most exciting stock." } },
  { id: "key-lessons", title: "Key Lessons", paragraphs: ["The research’s clearest lesson is that Apple should be understood as a customer-loyalty business. The iPhone draws customers into the ecosystem, integrated products make the relationship harder to leave, and Services extend it after the initial purchase.", "A second lesson is that consistency matters. Apple may not need exceptional year-over-year growth to support the author’s long-term case if it can preserve its profitability, cash generation, premium positioning, and ability to keep customers engaged."] },
];

const appleReadingWords = appleSections.flatMap((section) => [...(section.paragraphs ?? []), section.callout?.text ?? ""]).join(" ").trim().split(/\s+/).filter(Boolean).length;
const appleReadingTime = `${Math.ceil(appleReadingWords / 220)} min read`;

const apple: Company = { slug: "apple", name: "Apple Inc.", sector: "Consumer technology", coverageStatus: "Complete", readingTime: appleReadingTime, reportSummary: "An independent company research report on Apple’s ecosystem, Services, financial consistency, capital allocation, risks, and long-term investment thesis.", investmentSnapshot: [{ label: "Author view", value: "Positive, long term", detail: "A ten-year ownership case, not a short-term growth call." }, { label: "Core strength", value: "Customer loyalty", detail: "Ecosystem integration, switching costs, and premium pricing." }, { label: "Financial profile", value: "High profitability", detail: "Substantial revenue, profit, and cash generation across the supplied period." }, { label: "Primary watch items", value: "Growth & execution", detail: "iPhone upgrades, regulation, AI, supply chain, and premium demand." }, { label: "Valuation stance", value: "No conclusion", detail: "Historical approximate P/E context only." }], sectionOrder: ["executive-summary", "business-overview", "business-model", "revenue-breakdown", "competitive-advantages", "industry-context", "financial-performance", "capital-allocation", "risks", "valuation-context", "investment-thesis", "key-lessons"], sections: appleSections };

const amazonSections: ReportSection[] = [
  { id: "executive-summary", title: "Executive Summary", paragraphs: ["The Executive Memo presents Amazon as a business that has evolved beyond online retail into an interconnected system of commerce, AWS, advertising, Prime, logistics, and AI. The central investment case is that these activities strengthen one another instead of operating as unrelated businesses.", "The author’s long-term conclusion rests on AWS as the major profit engine, the continued expansion of the ecosystem, logistics as a competitive weapon, practical AI investment, and reinvestment-led capital allocation. The principal concerns are AWS competition, regulation, retail margins, capital intensity, consumer cyclicality, and the complexity of executing across several industries."], callout: { label: "Author conclusion", text: "Recommendation: BUY. Investment horizon: 10+ years. Author confidence rating: 9.4 / 10." } },
  { id: "business-overview", title: "Business Overview", paragraphs: ["The supplied research describes Amazon as a collection of connected businesses: first-party retail, third-party marketplace and seller services, AWS, advertising, Prime, logistics, and AI products. Retail remains the consumer-facing identity, while the author views the company increasingly as digital and physical infrastructure.", "Retail brings customers, Prime encourages repeat activity, advertising monetizes shopping behaviour, AWS provides a major profit engine, logistics supports the customer experience, and AI is described as improving several parts of the system. Other activities are mentioned in the research, but the supplied numerical source does not provide a complete segment breakdown." ] },
  { id: "business-model", title: "Business Model", paragraphs: ["Amazon earns retail revenue directly and through its marketplace, seller services, commissions, and fulfillment fees. The author emphasizes the platform shift: the company can profit from enabling other sellers rather than owning every product sold.", "The research describes an ecosystem in which customer activity attracts sellers, seller demand supports advertising, advertising improves profitability, and investment in AWS, logistics, Prime, and AI improves the wider customer proposition. This diagram represents that author framework, not a quantified causal model."], diagram: { title: "Amazon Ecosystem Flywheel", caption: "Author’s framework: retail activity, sellers, advertising, reinvestment, and customer experience reinforce Amazon’s connected businesses.", kind: "loop", nodes: [{ id: "customers", label: "Customers" }, { id: "sellers", label: "Sellers & selection" }, { id: "ads", label: "Advertising" }, { id: "investment", label: "AWS, logistics & AI" }], links: [{ from: "customers", to: "sellers" }, { from: "sellers", to: "ads" }, { from: "ads", to: "investment" }, { from: "investment", to: "customers", label: "experience" }] } },
  { id: "revenue-breakdown", title: "Revenue Breakdown", paragraphs: ["Amazon_Database_v1.docx records total revenue rising from US$469.82B in FY2021 to US$637.96B in FY2024. The research identifies retail, third-party seller services, AWS, advertising, and Prime-linked activity as key parts of the broader revenue architecture.", "AWS revenue increased from US$62.20B in FY2021 to US$107.56B in FY2024. The source package does not supply a reconciled retail, advertising, seller-services, subscription, or geographic revenue mix, so no full segment composition is inferred."] },
  { id: "competitive-advantages", title: "Competitive Advantages", paragraphs: ["The research identifies Amazon’s principal advantages as ecosystem integration, marketplace scale, Prime, logistics infrastructure, AWS operating experience, and purchase-intent advertising. It emphasizes that these advantages reinforce one another and are more difficult to reproduce as a connected system than individually.", "The author’s qualitative competitive analysis is retained here without publishing peer scores, star matrices, moat rankings, or a claim that Amazon has the strongest moat. The research argues instead that competitors often face multiple connected parts of Amazon’s business at once." ] },
  { id: "industry-context", title: "Industry Context", paragraphs: ["Amazon operates across e-commerce, cloud computing, digital advertising, AI infrastructure, enterprise software, subscription services, logistics, and media. The research sees continued cloud and enterprise-AI adoption as important context, while noting that competition remains intense in retail, cloud, and advertising.", "The author identifies AI products and infrastructure including Bedrock, Amazon Q, Nova, Trainium, Inferentia, and Alexa+ as part of Amazon’s strategy. The approach is described as infrastructure-led: enabling enterprises to build AI rather than depending on one consumer-facing product."], diagram: { title: "AWS AI Infrastructure Stack", caption: "Author’s framework: AWS infrastructure and custom chips support Bedrock, Amazon Q, Nova, and enterprise AI workloads; it does not claim standalone AI revenue.", kind: "flow", nodes: [{ id: "chips", label: "Trainium & Inferentia" }, { id: "aws", label: "AWS infrastructure" }, { id: "platforms", label: "Bedrock, Q & Nova" }, { id: "workloads", label: "Enterprise AI" }], links: [{ from: "chips", to: "aws" }, { from: "aws", to: "platforms" }, { from: "platforms", to: "workloads" }] } },
  { id: "financial-performance", title: "Financial Performance", paragraphs: ["Amazon_Database_v1.docx shows revenue increasing from US$469.82B in FY2021 to US$637.96B in FY2024. Operating income declined from US$24.88B in FY2021 to US$12.25B in FY2022 before increasing to US$68.59B in FY2024; EPS followed the same broad recovery pattern.", "Free cash flow was negative in FY2021 and FY2022 during the heavy investment cycle, then recovered to US$36.8B in FY2023 and US$38.2B in FY2024. Financial Analysis interprets that recovery as the outcome of investment in fulfillment, logistics, and infrastructure capacity rather than a simple reduction in ambition."], table: { caption: "Primary financial history from Amazon_Database_v1.docx. US$ billions except EPS; capex is approximate.", headers: ["Metric", "FY2021", "FY2022", "FY2023", "FY2024"], rows: [["Revenue", "469.82", "513.98", "574.79", "637.96"], ["Operating income", "24.88", "12.25", "36.85", "68.59"], ["EPS", "3.24", "-0.27", "2.90", "5.53"], ["Free cash flow", "-14.7", "-11.6", "36.8", "38.2"], ["Capex", "~61", "~63", "~53", "~83"], ["AWS revenue", "62.20", "80.10", "90.76", "107.56"]] } },
  { id: "capital-allocation", title: "Capital Allocation", paragraphs: ["The supplied research describes Amazon as reinvestment-led rather than dividend- or large-repurchase-led. It identifies fulfillment centers, data centers, AWS infrastructure, AI chips, logistics automation, robotics, and research and development as the areas management uses to strengthen long-term competitive advantages.", "The primary database records approximate FY2024 capex of US$83B. The report does not estimate returns on AI capex or assign the supplied capex to individual projects. The diagram therefore presents only the author’s qualitative capital-reinvestment framework."], diagram: { title: "Capital Reinvestment Path", caption: "Author’s framework: reinvestment supports fulfillment, data centers, AI infrastructure, logistics, robotics, and R&D to strengthen the wider system.", kind: "flow", nodes: [{ id: "cash", label: "Reinvestment" }, { id: "fulfillment", label: "Fulfillment & logistics" }, { id: "cloud", label: "Data centers & AI" }, { id: "rnd", label: "Robotics & R&D" }], links: [{ from: "cash", to: "fulfillment" }, { from: "cash", to: "cloud" }, { from: "cash", to: "rnd" }] } },
  { id: "risks", title: "Risks", paragraphs: ["Risk_Analysis identifies operational complexity as a central business risk: retail, AWS, advertising, Prime, logistics, and AI have different economics and priorities, while disruption across warehouses, transport, labor, and supply chains can ripple through the system.", "Other stated risks are cloud competition; retail, advertising, and marketplace competition; antitrust, privacy, and marketplace scrutiny; the returns and execution requirements of AI investment; capital intensity; valuation expectations; macroeconomic pressure on consumer spending and technology budgets; and the possibility of AI purchasing agents changing customer behaviour." ] },
  { id: "valuation-context", title: "Valuation Context", paragraphs: ["Valuation_Notes argues that Amazon is difficult to assess with a single conventional multiple because the company continuously reinvests in fulfillment, AWS, robotics, AI, logistics, and new business lines. The author discusses P/E, EV/EBITDA, and free cash flow as lenses, while noting the limits of each for a reinvestment-heavy company.", "The author’s Three-Lens Valuation Framework considers current financial strength, future cash-flow potential, and moat expansion. The conclusion is qualitative and reinvestment-sensitive: no current P/E, target price, fair value, DCF, or buy/sell timing is supplied or inferred." ] },
  { id: "investment-thesis", title: "Investment Thesis", paragraphs: ["The bull case rests on AWS benefiting from enterprise AI adoption, purchase-intent advertising, Prime’s role in loyalty and shopping behavior, logistics infrastructure, and AI products that improve AWS, operations, and customer experience. The supplied catalysts are AWS expansion, advertising demand, AI-enabled logistics efficiency, Prime’s evolving proposition, and optionality from Alexa+, Amazon Q, and Bedrock.", "The bear case is that Amazon competes in several demanding industries at once. Retail margins can remain thin, AWS competition is intense, capital expenditure requires patience, regulation can affect operations and acquisitions, execution is complex, and consumer spending is cyclical. The author nevertheless concludes that Amazon is building infrastructure behind commerce and increasingly behind AI."], callout: { label: "Final recommendation", text: "Author recommendation: BUY. Investment horizon: 10+ years. Author confidence rating: 9.4 / 10." } },
  { id: "key-lessons", title: "Key Lessons", paragraphs: ["The author’s central lesson is that Amazon should not be assessed only as a retailer. Retail brings customers, AWS brings a major profit engine, advertising improves economics, Prime supports loyalty, logistics supports convenience, and AI can strengthen each of those systems.", "A second lesson is that reinvestment is integral to the case. The research frames short-term pressure from large infrastructure spending as part of a long-term strategy to expand capacity, adaptability, and the competitive advantages that connect Amazon’s businesses." ] },
];

const amazonReadingWords = amazonSections.flatMap((section) => [...(section.paragraphs ?? []), section.callout?.text ?? ""]).join(" ").trim().split(/\s+/).filter(Boolean).length;
const amazon: Company = { slug: "amazon", name: "Amazon", sector: "E-commerce, cloud computing, and artificial intelligence", coverageStatus: "Complete", readingTime: `${Math.ceil(amazonReadingWords / 220)} min read`, reportSummary: "An independent company research report on Amazon’s connected retail, AWS, advertising, Prime, logistics, and AI businesses; financial performance; capital allocation; risks; valuation context; and long-term investment thesis.", investmentSnapshot: [{ label: "Author recommendation", value: "BUY", detail: "The author’s stated long-term conclusion." }, { label: "Investment horizon", value: "10+ years", detail: "Explicitly stated in the Investment Thesis." }, { label: "Author confidence", value: "9.4 / 10", detail: "Explicitly stated in the Investment Thesis." }, { label: "Core architecture", value: "Connected ecosystem", detail: "Retail, Prime, advertising, AWS, logistics, and AI reinforce one another in the author’s analysis." }, { label: "FY2024 financial profile", value: "US$637.96B revenue", detail: "US$68.59B operating income and US$38.2B free cash flow." }, { label: "Major profit engine", value: "AWS", detail: "FY2024 AWS revenue was US$107.56B in the primary database." }, { label: "Capital allocation", value: "Reinvestment-led", detail: "Approximate FY2024 capex of US$83B; the research emphasizes infrastructure and capability building." }, { label: "Valuation context", value: "Reinvestment-sensitive", detail: "Premium context without a fair value, target multiple, or target price." }, { label: "Primary watch items", value: "Execution & competition", detail: "AWS competition, regulation, retail margins, capital intensity, consumer cyclicality, and execution complexity." }], sectionOrder: ["executive-summary", "business-overview", "business-model", "revenue-breakdown", "competitive-advantages", "industry-context", "financial-performance", "capital-allocation", "risks", "valuation-context", "investment-thesis", "key-lessons"], sections: amazonSections };

const metaSections: ReportSection[] = [
  { id: "executive-summary", title: "Executive Summary", paragraphs: ["The Executive Memo presents Meta as a digital-platform business whose core economic engine is advertising across the Family of Apps. The report’s long-term case centers on engagement, data, AI-driven recommendations, and advertising infrastructure, with WhatsApp business messaging and AI assistants as prospective growth opportunities.", "The author balances that case against advertising cyclicality, privacy and regulatory pressure, competition for attention, uncertainty around Reality Labs, and AI competition. The research does not provide a detailed financial database, so this report retains the author’s qualitative financial interpretation rather than introducing unsupported figures."], callout: { label: "Author conclusion", text: "Author recommendation: BUY. Investment horizon: 10+ years. Author confidence rating: 9.3 / 10." } },
  { id: "business-overview", title: "Business Overview", paragraphs: ["The supplied research describes Meta as more than a social-media company: Facebook, Instagram, WhatsApp, Messenger, advertising tools, AI products, and Reality Labs form a connected set of platforms and investments. Family of Apps is the operating center of the report, while Reality Labs is treated as a longer-term and uncertain bet.", "The Executive Memo’s business snapshot is preserved as a concise guide to the research’s framing, not as a quantitative company profile."], table: { caption: "Business snapshot adapted from Executive_Memo.docx.", headers: ["Area", "Research framing"], rows: [["Core platforms", "Facebook, Instagram, WhatsApp, and Messenger"], ["Primary economic engine", "Digital advertising"], ["AI products named", "Meta AI, Llama, and AI Studio"], ["Growth focus", "AI-supported advertising and engagement"], ["Investment style", "Long-term compounder"]] } },
  { id: "business-model", title: "Business Model", paragraphs: ["The Business Model Analysis describes attention and interaction as the starting point of Meta’s model. Engagement across the Family of Apps produces signals that support recommendations and advertising relevance; advertising monetizes that activity and funds further investment in the platform.", "The report identifies business messaging, customer support, payments, AI, and enterprise tools as possible WhatsApp opportunities, while explicitly treating its monetisation as underdeveloped rather than providing a standalone revenue estimate."], diagram: { title: "Meta Attention-to-Advertising Flywheel", caption: "Author’s framework: engagement produces data and recommendation signals that support advertising, which funds further product and AI investment.", kind: "loop", nodes: [{ id: "engagement", label: "Family of Apps engagement" }, { id: "signals", label: "Data & recommendations" }, { id: "advertising", label: "Advertising" }, { id: "investment", label: "Product & AI investment" }], links: [{ from: "engagement", to: "signals" }, { from: "signals", to: "advertising" }, { from: "advertising", to: "investment" }, { from: "investment", to: "engagement" }] } },
  { id: "revenue-breakdown", title: "Revenue Breakdown", paragraphs: ["Digital advertising across the Family of Apps is the core economic engine identified throughout the supplied research. The package does not provide a reconciled revenue split by Facebook, Instagram, WhatsApp, or Messenger, and no such breakdown is inferred here.", "The author identifies business messaging and AI-supported tools as additional opportunities. They are discussed as potential future sources of monetisation, not as separately quantified revenue streams." ] },
  { id: "competitive-advantages", title: "Competitive Advantages", paragraphs: ["The Business Model Analysis identifies engagement, data, AI recommendations, advertising infrastructure, platform scale, and network effects as mutually reinforcing advantages. The report preserves the network-effects thesis because the supplied analysis explicitly supports it; it does not quantify its strength or compare it with peers.", "The author also emphasizes that Llama and other AI initiatives can support engagement and product improvement. The research does not attribute direct revenue to Llama or claim a quantified return on those investments."], diagram: { title: "Network Effects", caption: "Business Model Analysis framework: user participation, content and interactions, advertiser interest, and product investment reinforce one another. This is a qualitative thesis, not a measured effect.", kind: "loop", nodes: [{ id: "users", label: "Users & participation" }, { id: "content", label: "Content & interaction" }, { id: "advertisers", label: "Advertisers" }, { id: "product", label: "Product investment" }], links: [{ from: "users", to: "content" }, { from: "content", to: "advertisers" }, { from: "advertisers", to: "product" }, { from: "product", to: "users" }] } },
  { id: "industry-context", title: "Industry Context", paragraphs: ["The research places Meta in social platforms, digital advertising, AI, messaging, and immersive technology. It identifies competition for attention, including TikTok, as an important operating constraint, alongside privacy and regulatory developments that can affect advertising and product design.", "AI is presented as both an opportunity and a competitive requirement. The supplied analysis highlights improved recommendations, advertising tools, assistants, and open-source development, but does not provide market-share claims or an objective industry ranking."], diagram: { title: "WhatsApp Opportunity Map", caption: "Author’s framework: WhatsApp’s stated opportunities include business messaging, customer support, payments, AI, and enterprise tools; none is presented as quantified revenue.", kind: "flow", nodes: [{ id: "whatsapp", label: "WhatsApp" }, { id: "messaging", label: "Business messaging" }, { id: "support", label: "Customer support" }, { id: "tools", label: "Payments, AI & enterprise tools" }], links: [{ from: "whatsapp", to: "messaging" }, { from: "whatsapp", to: "support" }, { from: "whatsapp", to: "tools" }] } },
  { id: "financial-performance", title: "Financial Performance", paragraphs: ["Financial Analysis characterizes Family of Apps as profitable and cash-generative, and describes the business as having strong margins and the capacity to fund major investment. The supplied package does not include an auditable multi-year financial history, segment profit data, or detailed margin and cash-flow figures; those measures are intentionally not reconstructed here.", "The Executive Memo’s assessment is retained as the author’s qualitative view rather than as independently verified financial evidence."], table: { caption: "Qualitative assessment adapted from Executive_Memo.docx.", headers: ["Area", "Author assessment"], rows: [["Revenue", "Strong"], ["Operating margin", "Excellent"], ["Free cash flow", "Exceptional"], ["Balance sheet", "Extremely strong"], ["AI position", "Strong in the author’s assessment"], ["Long-term valuation framing", "Attractive relative to long-term growth in the author’s assessment"]] } },
  { id: "capital-allocation", title: "Capital Allocation", paragraphs: ["The supplied research describes capital allocation as directed toward AI infrastructure, data centers, Reality Labs, research and development, and share buybacks. Financial Analysis frames the ability to fund those commitments as a key feature of the underlying business.", "Reality Labs is treated as a long-term option with uncertainty rather than as a current return driver. The research does not provide detailed spending, buyback, or cash-flow figures, and the diagram is therefore a qualitative capital-allocation map."], diagram: { title: "AI Reinvestment Path", caption: "Author’s framework: advertising-supported cash generation funds AI infrastructure, data centers, R&D, Reality Labs, and share buybacks.", kind: "flow", nodes: [{ id: "cash", label: "Advertising cash generation" }, { id: "ai", label: "AI & data centers" }, { id: "rnd", label: "R&D & Reality Labs" }, { id: "returns", label: "Share buybacks" }], links: [{ from: "cash", to: "ai" }, { from: "cash", to: "rnd" }, { from: "cash", to: "returns" }] } },
  { id: "management-quality", title: "Management Quality", paragraphs: ["Management_Quality_Framework.docx supports a distinct qualitative assessment of management. Its discussion of Mark Zuckerberg emphasizes long-term vision, innovation, execution, adaptability, culture, shareholder alignment, crisis management, and moat expansion; it also notes the controversy and uncertainty embedded in large strategic bets.", "The report retains those dimensions without publishing the framework’s numerical score, peer-CEO scorecards, or comparative ranking. This keeps the section focused on the supplied qualitative judgment rather than turning it into a cross-company league table."], table: { caption: "Qualitative management dimensions adapted from Management_Quality_Framework.docx.", headers: ["Dimension", "Research emphasis"], rows: [["Long-term vision", "Willingness to pursue large strategic bets"], ["Innovation & adaptability", "Response to platform and AI change"], ["Execution", "Product and operating follow-through"], ["Capital allocation", "Balancing reinvestment with shareholder returns"], ["Culture & crisis management", "Leadership under strategic and public pressure"], ["Moat expansion", "Extending the platform’s long-term relevance"]] } },
  { id: "risks", title: "Risks", paragraphs: ["The supplied research identifies advertising cyclicality, privacy and regulation, competition for attention, Reality Labs uncertainty, and AI competition as the central risks. It also notes the possibility that product relevance can shift as competitors and consumer behavior change.", "The report does not quantify Reality Labs losses, regulatory exposure, or the financial cost of AI investment because the supplied package does not support those figures." ], table: { caption: "SWOT matrix adapted from Financial Analysis.docx; qualitative source framing only.", headers: ["Strengths", "Weaknesses", "Opportunities", "Threats"], rows: [["Billions of active users", "Heavy reliance on advertising", "AI assistants", "TikTok and other attention competition"], ["AI capabilities", "Reality Labs uncertainty", "WhatsApp monetisation", "Privacy and regulatory pressure"], ["Extensive data", "Regulatory scrutiny", "Business messaging", "Advertising downturns"], ["Strong margins in the author’s framing", "Limited hardware success", "AI advertising tools", "Open-source AI competition"]] } },
  { id: "valuation-context", title: "Valuation Context", paragraphs: ["The Investment Thesis frames valuation qualitatively rather than through a supplied DCF, fair value, target price, or current multiple. The author’s view balances possible AI and WhatsApp upside against the uncertainty associated with Reality Labs and the execution requirements of continued investment.", "The research also cautions that P/E alone is not a complete lens for a business funding long-term initiatives. No target multiple, timing guidance, or valuation conclusion beyond the author’s stated long-term view is added." ] },
  { id: "investment-thesis", title: "Investment Thesis", paragraphs: ["The author’s bull case rests on the attention and engagement of the Family of Apps, AI-supported recommendations and advertising, business-messaging opportunities, data, and the cash-generative ability to fund AI investment and buybacks. Stated catalysts include AI tools for advertising, WhatsApp business messaging, AI assistants, and continued engagement improvement.", "The bear case centers on advertising sensitivity, privacy and regulation, TikTok and other attention competitors, Reality Labs uncertainty, and AI competition. The Investment Thesis nevertheless concludes that Meta remains a long-term opportunity if it continues to adapt its products and translate AI investment into better experiences and advertising outcomes."], callout: { label: "Final recommendation", text: "Author recommendation: BUY. Investment horizon: 10+ years. Author confidence rating: 9.3 / 10." } },
  { id: "key-lessons", title: "Key Lessons", paragraphs: ["The author’s central lesson is that Meta should be understood as a connected attention, data, AI, and advertising system rather than as a collection of separate social applications. The report’s long-term case depends on whether product investment can sustain engagement and improve monetisation without undermining the user experience.", "A second lesson is that optionality is not the same as proven financial contribution. WhatsApp, AI assistants, Llama, and Reality Labs appear in the research as strategic opportunities or investments; the supplied package does not establish standalone revenue, returns, or valuation for them." ] },
];

