const meta: Company = { slug: "meta", name: "Meta", sector: "Digital platforms and advertising", coverageStatus: "Complete", readingTime: `${Math.ceil(metaReadingWords / 220)} min read`, reportSummary: "An independent company research report on Meta’s Family of Apps advertising engine, AI and messaging opportunities, qualitative financial and capital-allocation context, management quality, risks, and long-term investment thesis.", investmentSnapshot: [{ label: "Author recommendation", value: "BUY", detail: "The author’s stated long-term conclusion." }, { label: "Investment horizon", value: "10+ years", detail: "Explicitly stated in the Investment Thesis." }, { label: "Author confidence", value: "9.3 / 10", detail: "Explicitly stated in the Investment Thesis." }, { label: "Core economic engine", value: "Digital advertising", detail: "Advertising across the Family of Apps is the core engine identified in the research." }, { label: "Core advantage", value: "Engagement, data & AI", detail: "The author connects engagement, data, AI recommendations, advertising infrastructure, and supported network effects." }, { label: "Growth opportunities", value: "WhatsApp & AI", detail: "Business messaging and AI assistants are stated opportunities, not quantified revenue streams." }, { label: "Capital allocation", value: "Reinvestment & buybacks", detail: "AI infrastructure, data centers, Reality Labs, R&D, and share buybacks." }, { label: "Valuation context", value: "Qualitative", detail: "Potential AI and WhatsApp upside is balanced against Reality Labs uncertainty; no fair value is supplied." }, { label: "Primary watch items", value: "Attention & execution", detail: "Advertising cyclicality, privacy and regulation, competition, Reality Labs, and AI execution." }], sectionOrder: ["executive-summary", "business-overview", "business-model", "revenue-breakdown", "competitive-advantages", "industry-context", "financial-performance", "capital-allocation", "management-quality", "risks", "valuation-context", "investment-thesis", "key-lessons"], sections: metaSections };

const visaSections: ReportSection[] = [
  { id: "executive-summary", title: "Executive Summary", paragraphs: ["The Executive Memo presents Visa as an electronic payment-network business: it routes payments among consumers, merchants, and financial institutions rather than lending money or taking direct credit risk. The long-term case rests on the continuing shift from cash to digital payments, network effects, trust, scale, and a model that remains relatively low in capital intensity.", "The author identifies e-commerce, cross-border activity, emerging-market adoption, AI-supported fraud prevention, and value-added services as growth drivers. The principal watch items are regulation, alternative payment rails, competition, spending cycles, cybersecurity, and the possibility that AI also improves the capabilities of attackers."], callout: { label: "Author conclusion", text: "Author recommendation: BUY. Investment horizon: 10+ years. Author conviction: 9.4 / 10." } },
  { id: "business-overview", title: "Business Overview", paragraphs: ["Visa operates payment infrastructure. In the author’s description, a merchant initiates a payment request, Visa routes it to the issuing bank, the bank evaluates funds or available credit, and the authorization returns through the network. Visa earns fees for enabling that process rather than for issuing loans or collecting interest.", "This distinction shapes the report’s framing: Visa participates in the growth of electronic commerce and payment volume without directly funding customer credit. The supplied research describes its role as an infrastructure layer that can remain present whether people pay with cards, wallets, wearables, or online interfaces."], diagram: { title: "Visa Payment Authorization Flow", caption: "Business Model Analysis framework: Visa routes the authorization request between the merchant side and issuing bank; it does not lend the funds.", kind: "flow", nodes: [{ id: "merchant", label: "Merchant payment request" }, { id: "visa", label: "Visa network" }, { id: "issuer", label: "Issuing bank" }, { id: "approval", label: "Authorization response" }], links: [{ from: "merchant", to: "visa" }, { from: "visa", to: "issuer" }, { from: "issuer", to: "approval" }, { from: "approval", to: "merchant" }] } },
  { id: "business-model", title: "Business Model", paragraphs: ["The research separates Visa’s revenue architecture into service revenue, data-processing revenue, international transaction revenue, and value-added services. Service revenue reflects network access and payment volume; data-processing revenue is tied to approved transaction routing; international activity can carry higher fees because processing is more complex.", "Value-added services named in the research include fraud detection, cybersecurity, risk management, data analytics, tokenisation, and consulting. The supplied package does not provide amounts for these revenue streams, so the report explains the architecture without estimating a segment mix."], diagram: { title: "Revenue Architecture", caption: "Business Model Analysis framework: Visa’s listed revenue sources are service revenue, data processing, international transactions, and value-added services; the source does not provide a quantified mix.", kind: "flow", nodes: [{ id: "network", label: "Payment network" }, { id: "service", label: "Service revenue" }, { id: "processing", label: "Data processing" }, { id: "international", label: "International transactions" }, { id: "vas", label: "Value-added services" }], links: [{ from: "network", to: "service" }, { from: "network", to: "processing" }, { from: "network", to: "international" }, { from: "network", to: "vas" }] } },
  { id: "revenue-breakdown", title: "Revenue Breakdown", paragraphs: ["The Business Model Analysis names transaction and service fees as the main revenue sources, organized across service revenue, data processing, international transactions, and value-added services. Cross-border activity is described as a higher-fee opportunity, while fraud, cybersecurity, analytics, tokenisation, and consulting broaden the service offering.", "No reconciled revenue or profit split by source, geography, card type, customer group, or product is included in the package. The report therefore does not create a quantitative composition chart or infer one from the overall revenue figure." ] },
  { id: "competitive-advantages", title: "Competitive Advantages", paragraphs: ["The supplied Business Model Analysis identifies global acceptance, network effects, brand trust, scale, data-supported fraud intelligence, and low capital intensity as reinforcing advantages. More consumers encourage more merchant acceptance; greater acceptance attracts issuing institutions; transaction activity can improve fraud detection; dependable execution reinforces trust.", "Competitive Positioning adds useful qualitative context: Mastercard has a similar network model, while American Express carries lending and direct-customer exposure, and some digital wallets can operate over Visa’s rails. The report excludes the supplied peer scores, rankings, and claims of objectively superior moat strength."], diagram: { title: "Visa Trust and Network Flywheel", caption: "Author’s framework: consumer use, merchant acceptance, issuing institutions, transaction data, fraud intelligence, and trust reinforce one another. It is qualitative, not a measured model.", kind: "loop", nodes: [{ id: "consumers", label: "Consumers" }, { id: "merchants", label: "Merchant acceptance" }, { id: "issuers", label: "Issuing institutions" }, { id: "data", label: "Transactions & data" }, { id: "trust", label: "Fraud intelligence & trust" }], links: [{ from: "consumers", to: "merchants" }, { from: "merchants", to: "issuers" }, { from: "issuers", to: "data" }, { from: "data", to: "trust" }, { from: "trust", to: "consumers" }] } },
  { id: "industry-context", title: "Industry Context", paragraphs: ["The author’s industry context is shaped by the continuing movement from cash to electronic payments, e-commerce, cross-border commerce, and emerging-market digitisation. The research also treats digital wallets, fintech platforms, real-time bank transfers, account-to-account payment networks, and central bank digital currencies as part of the evolving payments landscape.", "AI is presented as an enabler rather than a replacement for the existing model. The sources describe uses in fraud detection, transaction monitoring, customer authentication, payment security, and risk analytics through banking partners; they do not quantify AI revenue or a financial return on those activities."], diagram: { title: "AI Fraud and Security Loop", caption: "Author’s framework: transaction activity provides signals for fraud detection and monitoring; stronger security supports trust and continued network use. The same research also recognizes AI-enabled criminal activity as a risk.", kind: "loop", nodes: [{ id: "transactions", label: "Transaction signals" }, { id: "detection", label: "Fraud detection & monitoring" }, { id: "security", label: "Security & authentication" }, { id: "trust", label: "Trust & network use" }], links: [{ from: "transactions", to: "detection" }, { from: "detection", to: "security" }, { from: "security", to: "trust" }, { from: "trust", to: "transactions" }] } },
  { id: "financial-performance", title: "Financial Performance", paragraphs: ["The workbook records FY2024 revenue of US$35.9B. Its header, however, describes the remaining summary as “FY2024 / TTM Approx.” The operating margin, net margin, free cash flow, ROE, capex, and buyback values below are therefore presented as approximate supplied metrics rather than as one perfectly reconciled fiscal-year dataset.", "Financial Analysis interprets the model qualitatively as highly scalable, profitable, cash-generative, and relatively low in capital requirements. It attributes the economics to the ability to process additional transactions without proportionate cost growth and to the absence of direct lending exposure."], table: { caption: "Metrics from Untitled spreadsheet.xlsx. Revenue is specifically FY2024; the workbook header describes the remaining metrics as FY2024 / TTM approximate, so they should not be read as one reconciled fiscal-year dataset.", headers: ["Metric", "Supplied value", "Period / basis"], rows: [["Revenue", "US$35.9B", "FY2024"], ["Operating margin", "~66%", "FY2024 / TTM approximate"], ["Net margin", "~55%", "FY2024 / TTM approximate"], ["Free cash flow", "~US$19.8B", "FY2024 / TTM approximate"], ["ROE", "~52%", "FY2024 / TTM approximate"], ["Capital expenditure", "~US$1.1B", "FY2024 / TTM approximate"], ["Share buybacks", "~US$17.0B", "FY2024 / TTM approximate"]] }, tables: [{ caption: "Qualitative assessment adapted from Executive Memo.docx.", headers: ["Category", "Author assessment"], rows: [["Revenue growth", "Strong & consistent"], ["Operating margin", "Exceptional"], ["Free cash flow", "Outstanding"], ["Balance sheet", "Excellent"], ["AI position", "Strengthening the core business"], ["Valuation", "Premium but justified"]] }] },
  { id: "capital-allocation", title: "Capital Allocation", paragraphs: ["Financial Analysis describes a balance among investment in payment technology and cybersecurity, strategic acquisitions, and the return of excess cash through share buybacks. The workbook lists approximate capex of US$1.1B and share buybacks of US$17.0B under its mixed FY2024 / TTM approximate heading.", "The research characterizes strong free cash flow and modest capital requirements as giving management flexibility. It does not allocate spending by initiative or measure the return on individual acquisitions, AI investment, cybersecurity work, or repurchases."], diagram: { title: "Capital Allocation Flow", caption: "Financial Analysis framework: cash generation supports technology and cybersecurity, acquisitions, and share buybacks. It does not assign the supplied metrics to individual uses.", kind: "flow", nodes: [{ id: "fcf", label: "Cash generation" }, { id: "technology", label: "Technology & cybersecurity" }, { id: "acquisitions", label: "Strategic acquisitions" }, { id: "buybacks", label: "Share buybacks" }], links: [{ from: "fcf", to: "technology" }, { from: "fcf", to: "acquisitions" }, { from: "fcf", to: "buybacks" }] } },
  { id: "risks", title: "Risks", paragraphs: ["Risk Analysis identifies regulation as the most important long-term uncertainty, with scrutiny of fees, competition, merchant pricing, consumer protection, and data privacy. Other risks include Mastercard and fintech competition, alternative payment rails, consumer-spending and cross-border activity cycles, cybersecurity, and AI-enabled criminal techniques.", "The report preserves the source’s severity structure but omits its aggregate 3.5 / 10 risk score. The severity labels are qualitative author assessments rather than a calibrated probability model."], table: { caption: "Risk severity table adapted from Risk Analysis.docx. The source’s aggregate risk score is intentionally omitted.", headers: ["Risk category", "Author severity", "Source framing"], rows: [["Business", "Low", "Diversified transaction base and global footprint"], ["Competitive", "Medium", "Mastercard and fintechs remain strong as the market expands"], ["Regulatory", "High", "The biggest long-term uncertainty in the source analysis"], ["AI & cyber", "Medium", "AI helps defenders and attackers; continued investment is necessary"], ["Financial", "Low", "Margins and cash flow provide resilience in the author’s framing"]] } },
  { id: "valuation-context", title: "Valuation Context", paragraphs: ["Valuation Notes argues that Visa’s premium-quality framing should be considered through business quality, growth quality, and price quality rather than through one multiple alone. It discusses P/E, EV/EBITDA, and free cash flow as lenses, while emphasizing network effects, predictability, cash conversion, and low capital intensity.", "The report does not treat the source’s illustrative 28× and 32× references as current valuation data. No current multiple, fair value, price target, DCF, or timing guidance is supplied or inferred."], table: { caption: "Three-layer valuation framework preserved from Valuation Notes.docx.", headers: ["Layer", "Question"], rows: [["Business quality", "Is this an exceptional business?"], ["Growth quality", "Can earnings compound for many years?"], ["Price quality", "Am I paying a sensible price for that quality?"]] } },
  { id: "investment-thesis", title: "Investment Thesis", paragraphs: ["The author’s bull case rests on digital payments replacing cash, e-commerce, cross-border activity, emerging-market adoption, network effects, AI-supported fraud prevention, strong cash generation, and disciplined capital allocation. Stated catalysts include continued digital-commerce growth, emerging-market expansion, cross-border transactions, AI-powered fraud prevention, and additional value-added services.", "The bear case centers on regulation, Mastercard and fintech competition, alternative rails, slower consumer spending, cybersecurity threats, and the difficulty of maintaining high growth at large scale. The Investment Thesis nevertheless concludes that Visa remains a high-quality long-term business because it participates in gradual changes in payment behaviour rather than depending on a single breakthrough product."], callout: { label: "Final recommendation", text: "Author recommendation: BUY. Investment horizon: 10+ years. Author conviction: 9.4 / 10." } },
  { id: "key-lessons", title: "Key Lessons", paragraphs: ["The research’s central lesson is that Visa is best understood as payment infrastructure rather than a lender or a conventional card company. Its economic role is to connect participants and earn fees as commerce moves through the network.", "A second lesson is that trust and interoperability are central to the thesis. The author’s network-effects framework links acceptance, institutions, transactions, data, security, and continued use, while recognizing that regulatory change and alternative rails remain the main tests of that long-term advantage." ] },
];

