const moodysSections: ReportSection[] = [
  { id: "executive-summary", title: "Executive Summary", paragraphs: ["The supplied research presents Moody’s as a trusted financial-infrastructure business that helps markets assess credit risk. Its core functions are provided through Moody’s Ratings, which supplies credit opinions and ratings, and Moody’s Analytics, which supplies risk-management software, data, models, regulatory tools, and subscription services.", "The author’s long-term case rests on reputation, regulatory recognition, historical data, pricing power, asset-light economics, recurring Analytics revenue, and growing demand for financial intelligence as debt markets and financial complexity expand. Principal watch items are debt issuance, interest rates, regulation, reputation, competition, AI, and geopolitical fragmentation."], callout: { label: "Author view", text: "The supplied thesis frames Moody’s as a long-term compounder and trusted financial-infrastructure business. Its subjective 9.5 / 10 score is not presented as an objective metric here." } },
  { id: "business-overview", title: "Business Overview", paragraphs: ["Moody’s is described as a financial-information business whose credit opinions help governments, corporations, banks, insurers, pension funds, asset managers, and other market participants assess credit risk. The author’s central formulation is that Moody’s sells confidence: it reduces the cost of evaluating borrowers and helps capital markets function more efficiently.", "The source package separates the business into Moody’s Ratings and Moody’s Analytics. Ratings is the established credit-opinion franchise and is more exposed to capital-market issuance activity; Analytics extends the business into recurring software, data, models, research, and risk-management tools."], diagram: { title: "Ratings and Analytics Architecture", caption: "Business Model Analysis framework: Moody’s Ratings provides credit opinions and Ratings-related research, while Moody’s Analytics provides software, data, models, and subscription services.", kind: "flow", nodes: [{ id: "moodys", label: "Moody’s" }, { id: "ratings", label: "Moody’s Ratings" }, { id: "analytics", label: "Moody’s Analytics" }, { id: "customers", label: "Capital-market participants" }], links: [{ from: "moodys", to: "ratings" }, { from: "moodys", to: "analytics" }, { from: "ratings", to: "customers" }, { from: "analytics", to: "customers" }] } },
  { id: "business-model", title: "Business Model", paragraphs: ["Moody’s Ratings earns fees when governments, corporations, municipalities, structured-finance issuers, and other borrowers seek credit assessments in connection with debt issuance. The source describes this as an issuer-pays model: the issuer typically pays for the rating, while investors use trusted credit opinions in their decisions.", "Moody’s Analytics earns recurring subscription revenue from annual software subscriptions, financial databases, risk-management platforms, regulatory-compliance tools, economic forecasting, credit modeling, AI-driven analytics, and climate-risk solutions. The research treats this recurring model as a stabilizing complement to the more cyclical Ratings franchise."], diagram: { title: "Revenue Resilience Architecture", caption: "Author’s framework: Ratings fees are linked to debt-market activity, while Analytics subscriptions provide a recurring revenue component. The source does not provide a quantified segment mix.", kind: "flow", nodes: [{ id: "ratings", label: "Ratings fees" }, { id: "issuance", label: "Debt issuance activity" }, { id: "analytics", label: "Analytics subscriptions" }, { id: "recurring", label: "Recurring revenue" }], links: [{ from: "issuance", to: "ratings" }, { from: "analytics", to: "recurring" }] } },
  { id: "revenue-breakdown", title: "Revenue Breakdown", paragraphs: ["The supplied research identifies two primary revenue engines: Ratings fees and Analytics subscription revenue. Ratings is naturally cyclical because debt issuance responds to interest rates, market conditions, and financing activity; Analytics is described as more recurring because customers subscribe to software, data, and risk-management tools.", "The package does not provide a reconciled Ratings-versus-Analytics revenue or profit split. This report preserves the architecture without publishing unsupported segment composition, customer concentration, or geographic revenue figures." ] },
  { id: "competitive-advantages", title: "Competitive Advantages", paragraphs: ["The author identifies reputation, regulatory recognition, historical data, brand, global reach, customer relationships, high switching costs, and trust as Moody’s core advantages. In this framing, an opinion is valuable not just because it is analytically sound, but because market participants, institutions, and regulations recognize and rely on it.", "The Business Model Analysis characterizes the industry as concentrated and notes S&P Global Ratings and Fitch Ratings as meaningful competitors. The report retains that context without publishing peer rankings, market-share claims, or an objective claim of superiority."], diagram: { title: "Moody’s Trust Pyramid", caption: "Business Model Analysis framework: issuers, investors, banks and insurers, asset managers, and other market participants rely on a shared foundation of trusted credit assessment.", kind: "flow", nodes: [{ id: "issuers", label: "Governments & corporate issuers" }, { id: "institutions", label: "Banks & insurers" }, { id: "investors", label: "Investors & asset managers" }, { id: "trust", label: "Trusted credit assessment" }], links: [{ from: "issuers", to: "trust" }, { from: "institutions", to: "trust" }, { from: "investors", to: "trust" }] } },
  { id: "industry-context", title: "Industry Context", paragraphs: ["The research links Moody’s opportunity to the ongoing complexity of debt markets, private credit, cross-border investing, regulation, climate disclosures, alternative assets, and AI risk. The author calls this the Complexity Dividend: more uncertainty and more complicated financial decisions can increase demand for trusted analysis.", "Debt issuance and interest rates remain important cyclical forces for Ratings. Analytics, financial intelligence, compliance, and risk-management tools are presented as growth areas that can broaden the business beyond the timing of a single bond-issuance cycle."], diagram: { title: "Complexity Dividend", caption: "Investment Thesis framework: growing financial complexity increases demand for trusted analysis, supporting the relevance of Ratings and Analytics. It is a qualitative demand thesis, not a quantified forecast.", kind: "flow", nodes: [{ id: "complexity", label: "Debt, regulation & complexity" }, { id: "demand", label: "Demand for trusted analysis" }, { id: "ratings", label: "Credit opinions" }, { id: "analytics", label: "Analytics & risk tools" }], links: [{ from: "complexity", to: "demand" }, { from: "demand", to: "ratings" }, { from: "demand", to: "analytics" }] } },
  { id: "financial-performance", title: "Financial Performance", paragraphs: ["Financial Analysis supplies an approximate five-year history. Revenue declined in 2022 as debt issuance slowed in a higher-rate environment, then recovered by 2024. The author interprets this as Ratings cyclicality rather than structural decline, and sees Analytics subscriptions as helping to improve resilience.", "All figures below are approximate source figures from Financial Analysis. They are preserved as supplied and are not independently reconciled or extended."], table: { caption: "Approximate five-year financial history from Financial_Analysis.docx. Figures are source estimates and have not been independently reconciled. Revenue and free cash flow are US$ billions.", headers: ["Metric", "2020", "2021", "2022", "2023", "2024"], rows: [["Revenue", "5.4", "6.2", "5.5", "5.9", "~7.1"], ["Operating margin", "~46%", "~49%", "~43%", "~45%", "~48%"], ["Net margin", "~29%", "~32%", "~27%", "~29%", "~30%"], ["Free cash flow", "~2.0", "~2.3", "~1.8", "~2.1", "~2.5"]] }, tables: [{ caption: "Five-year trend summary preserved from Financial_Analysis.docx.", headers: ["Metric", "Source trend", "Source interpretation"], rows: [["Revenue", "↑", "Long-term growth despite cyclical fluctuations"], ["Operating margin", "→ / ↑", "Consistently high, reflecting pricing power and scalability"], ["Net margin", "→", "Stable profitability across market environments"], ["ROE", "↑", "Strong capital efficiency, supported by buybacks"], ["ROIC", "↑", "Excellent reinvestment economics"], ["Free cash flow", "↑", "Healthy cash generation and disciplined capital allocation"], ["Analytics revenue", "↑", "Growing share of recurring subscription income"]] }] },
  { id: "capital-allocation", title: "Capital Allocation", paragraphs: ["The source materials describe management as balancing share repurchases, dividends, acquisitions, and technology investment while preserving financial flexibility. Financial Analysis also emphasizes the advantages of limited physical-capital requirements in a business whose principal assets are data, software, intellectual property, reputation, and people.", "The supplied research provides no annual buyback, dividend, acquisition, capex, debt, or share-count history. Capital allocation is therefore presented as the author’s qualitative framework rather than as a quantified record." ] },
  { id: "risks", title: "Risks", paragraphs: ["The research identifies cyclical debt issuance as the principal operating risk: higher rates or weaker markets can reduce bond issuance and Ratings activity. Other stated risks are regulatory intervention, reputation damage, competition from S&P Global Ratings and Fitch Ratings, AI changing barriers to credit analysis, interest-rate sensitivity, and geopolitical fragmentation.", "The author distinguishes institutional risks from short-term technology noise. The source’s central caution is that trust is Moody’s greatest asset and greatest vulnerability: a credibility failure could matter far more than a single weak quarter." ] },
  { id: "valuation-context", title: "Valuation Context", paragraphs: ["The Investment Thesis presents Moody’s as a premium-quality business whose valuation should be viewed alongside durable trust, pricing power, asset-light economics, recurring Analytics revenue, cash generation, and returns on capital. The author argues that quality and investment value are related but not identical.", "Timing-oriented guidance about when Moody’s may be attractive or when investors should be cautious is intentionally omitted. No current multiple, target price, fair value, DCF, or trading guidance is supplied or inferred." ] },
  { id: "investment-thesis", title: "Investment Thesis", paragraphs: ["The author’s bull case rests on global debt, an increasingly important Analytics franchise, the trust moat, capital-light economics, and capital allocation. The stated growth drivers include risk-management software, compliance, financial intelligence, economic forecasting, climate-risk analysis, AI-powered analytics, private credit, and a broader rise in financial complexity.", "The bear case centers on cyclical Ratings revenue, regulation, AI lowering the cost of credit analysis, reputation risk, rates, and competitive pressure. The author’s conclusion is that Moody’s may not become dramatically different over the next decade, but can become incrementally stronger as the demand for trusted financial intelligence persists."], callout: { label: "Author’s long-term conclusion", text: "The supplied thesis presents Moody’s as a quiet long-term compounder rooted in trust, pricing power, capital-light economics, Analytics recurrence, and financial complexity. The author’s subjective rating is intentionally omitted." } },
  { id: "key-lessons", title: "Key Lessons", paragraphs: ["The author’s central lesson is that Moody’s does not merely sell ratings: it sells confidence that allows lenders, issuers, investors, and regulators to make decisions more efficiently. That credibility is harder to replicate than analytical software alone.", "A second lesson is the interaction between Ratings and Analytics. Ratings can be cyclical with debt issuance, while Analytics subscriptions create a more recurring component; together, they underpin the research’s view of a business that can compound through cycles without requiring heavy physical capital." ] },
];

